import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { after, describe, it } from "node:test";

// Path-hygiene contract: a benchmark directory is relocatable. The foundry
// records only benchmark-dir-relative paths inside its artifacts, and every
// hub loader resolves against the directory it found the artifact in — so
// moving the whole tree (e.g. into ~/.understudy/) breaks nothing. The
// fixture is generated by the REAL in-tree foundry, then physically moved.
import { compileTraceFoundry } from "../../../dist/trace-foundry.js";
import { makeBenchmarkReview, serializeReviewLine } from "./.build/lib/artifacts-core.js";
import { captureFilePath, getEntry } from "./.build/lib/data-core.js";

const originalRoot = fs.mkdtempSync(path.join(os.tmpdir(), "bench-hub-reloc-a-"));
const movedRoot = fs.mkdtempSync(path.join(os.tmpdir(), "bench-hub-reloc-b-"));
delete process.env.BENCHMARK_HUB_DEMO;
after(() => {
  fs.rmSync(originalRoot, { recursive: true, force: true });
  fs.rmSync(movedRoot, { recursive: true, force: true });
});

const capture = (id, ts, messages, response) => ({
  schema_version: 4,
  request_id: id,
  ts,
  customer_request_body: JSON.stringify({
    system: "Operate a synthetic board.",
    messages,
    tools: [{ name: "update-record", input_schema: { type: "object" } }],
  }),
  response_body: JSON.stringify(response),
  status_code: 200,
});

// Generate a genuine foundry benchmark in the ORIGINAL location.
const source = path.join(originalRoot, "captures-src");
fs.mkdirSync(source, { recursive: true });
fs.writeFileSync(
  path.join(source, "captures.jsonl"),
  [
    capture("round-1", "2026-07-20T12:00:00Z", [{ role: "user", content: "Set record 7 active" }], {
      content: [{ type: "tool_use", id: "c1", name: "update-record", input: { id: 7 } }],
      stop_reason: "tool_use",
    }),
    capture(
      "round-2",
      "2026-07-20T12:00:01Z",
      [
        { role: "user", content: "Set record 7 active" },
        { role: "assistant", content: [{ type: "tool_use", id: "c1", name: "update-record", input: { id: 7 } }] },
        { role: "user", content: [{ type: "tool_result", tool_use_id: "c1", content: '{"ok":true}' }] },
      ],
      { content: [{ type: "text", text: "Done" }], stop_reason: "end_turn" },
    ),
  ]
    .map((r) => JSON.stringify(r))
    .join("\n") + "\n",
);
const benchDir = path.join(originalRoot, "relocatable-demo");
compileTraceFoundry(source, benchDir, 36500, new Date("2026-07-21T12:00:00Z"));

// A review and an eval row land next to the manifest before the move.
process.env.BENCHMARK_HUB_DATA_DIR = originalRoot;
const before = getEntry("data--relocatable-demo");
assert.equal(before.kind, "proposed");
const taskId = before.tasks[0].task_id;
fs.appendFileSync(
  path.join(benchDir, "reviews.jsonl"),
  serializeReviewLine(makeBenchmarkReview({ benchmark_id: "relocatable-demo", task_id: taskId, decision: "accept" })),
);
fs.appendFileSync(
  path.join(benchDir, "rows-run-x-model.jsonl"),
  JSON.stringify({ schema_version: "understudy.eval_result.v1", run_id: "run-x", task_id: taskId, split: "dev", score: 1, status: "ok" }) + "\n",
);

// Relocate: physically move the benchmark dir to a different root.
fs.renameSync(benchDir, path.join(movedRoot, "relocatable-demo"));
process.env.BENCHMARK_HUB_DATA_DIR = movedRoot;

describe("benchmark directory relocation", () => {
  it("recorded artifact paths are relative (nothing baked to the original root)", () => {
    const manifest = JSON.parse(fs.readFileSync(path.join(movedRoot, "relocatable-demo", "manifest.json"), "utf8"));
    for (const [key, value] of Object.entries(manifest.artifacts)) {
      assert.ok(!path.isAbsolute(value), `manifest.artifacts.${key} must be relative, got ${value}`);
    }
  });

  it("the moved dir loads fully: tasks, dag, reviews, rows", () => {
    const entry = getEntry("data--relocatable-demo");
    assert.equal(entry.kind, "proposed");
    assert.equal(entry.tasks.length, before.tasks.length);
    assert.equal(entry.dag.schema_version, "understudy.source_dag.v1");
    assert.equal(entry.reviews.length, 1);
    assert.equal(entry.latestReviewByTask[taskId].decision, "accept");
    assert.equal(entry.rows.length, 1);
    assert.deepEqual(entry.crossCheckErrors, []);
  });

  it("capture bodies still resolve after the move (hash-derived, dir-anchored)", () => {
    const entry = getEntry("data--relocatable-demo");
    for (const ref of entry.captureIndex) {
      const file = captureFilePath(entry, ref.capture_id);
      assert.ok(file.startsWith(movedRoot), `capture path anchored to the new root: ${file}`);
      assert.ok(fs.existsSync(file), `capture body exists after move: ${file}`);
    }
    assert.ok(entry.captureIndex.length > 0);
  });
});
